using DarouichTravaux.Application; using DarouichTravaux.Domain; using DarouichTravaux.Infrastructure;
namespace DarouichTravaux.Tests; public sealed class BusinessRulesTests { [Fact] public void Totals_include_tax(){ var result=InvoiceRules.Calculate([new("Béton","m³",2,100,20)]); Assert.Equal((200m,40m,240m),result); } [Fact] public void Invoice_filename_keeps_client_and_number(){ var i=new Invoice{Number="FAC-2026-018",Client=new Client{Name="Ahmed  El / Mansouri"}}; Assert.Equal("Facture(Ahmed_El_Mansouri)-FAC-2026-018.pdf",InvoiceFileNames.Build(i)); } [Fact] public void Empty_invoice_is_rejected()=>Assert.Throws<ArgumentException>(()=>InvoiceRules.Calculate([])); }
